import { it, expect, vi, afterEach } from "vitest";
import { reportClientError } from "./report-client-error";
import { handleClientError } from "./client-error-api";

afterEach(() => vi.unstubAllGlobals());

it("never throws, even for a thrown value String() cannot convert", () => {
  expect(() => reportClientError(Object.create(null))).not.toThrow();
});

// Generated by /ship test-coverage audit.
// Value: protects=the beacon the error screen sends is what the Worker's /api/client-error logs (URL, message, digest, path);
// fails_when=a field is renamed on one side, the URL path drifts, or the digest is dropped; why_new=the existing case only checks
// it never throws; seam=none; no_claim=real sendBeacon delivery and CORS (stubbed navigator/location; unit only)
it("sends a beacon the Worker's crash-report handler logs field for field", async () => {
  const sendBeacon = vi.fn<(url: string, body: string) => boolean>(() => true);
  vi.stubGlobal("navigator", { sendBeacon });
  vi.stubGlobal("location", { pathname: "/room/ABCD/screen" });
  reportClientError(Object.assign(new Error("boom"), { digest: "d1" }));
  reportClientError("plain string");

  expect(sendBeacon).toHaveBeenCalledTimes(2);
  const lines: string[] = [];
  for (const [url, body] of sendBeacon.mock.calls) {
    expect(url).toMatch(/\/api\/client-error$/);
    const req = new Request(url, { method: "POST", body, headers: { Origin: "https://app.example.com" } });
    expect((await handleClientError(req, "https://app.example.com", (l) => lines.push(l))).status).toBe(204);
  }
  expect(lines.map((l) => JSON.parse(l))).toEqual([
    { event: "client_error", message: "boom", digest: "d1", path: "/room/ABCD/screen" },
    { event: "client_error", message: "plain string", path: "/room/ABCD/screen" },
  ]);
});
